package com.optarena.tasktracker;

import static org.hamcrest.Matchers.containsInAnyOrder;
import static org.hamcrest.Matchers.empty;
import static org.hamcrest.Matchers.is;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.jayway.jsonpath.JsonPath;
import com.optarena.tasktracker.repository.ProjectRepository;
import com.optarena.tasktracker.repository.TaskRepository;
import com.optarena.tasktracker.repository.UserRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

@SpringBootTest
@AutoConfigureMockMvc
class TaskLabelsHiddenTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private UserRepository userRepository;

    @Autowired
    private ProjectRepository projectRepository;

    @Autowired
    private TaskRepository taskRepository;

    @BeforeEach
    void resetState() {
        userRepository.clear();
        projectRepository.clear();
        taskRepository.clear();
    }

    private int createProject() throws Exception {
        String userBody = mockMvc.perform(post("/users")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"username\":\"dev\",\"email\":\"dev@example.com\"}"))
                .andReturn().getResponse().getContentAsString();
        int userId = JsonPath.read(userBody, "$.id");
        String projBody = mockMvc.perform(post("/projects")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"Mercury\",\"ownerId\":" + userId + "}"))
                .andReturn().getResponse().getContentAsString();
        return JsonPath.read(projBody, "$.id");
    }

    @Test
    void labelsDefaultEmptyAndSettable() throws Exception {
        int projectId = createProject();

        mockMvc.perform(post("/tasks")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"A\",\"projectId\":" + projectId + "}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.labels", empty()));

        mockMvc.perform(post("/tasks")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"B\",\"projectId\":" + projectId + ",\"labels\":[\"bug\",\"urgent\"]}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.labels", containsInAnyOrder("bug", "urgent")));
    }

    @Test
    void labelFilterComposesWithStatus() throws Exception {
        int projectId = createProject();
        mockMvc.perform(post("/tasks")
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"title\":\"A\",\"projectId\":" + projectId + ",\"labels\":[\"bug\"]}"));
        String t2Body = mockMvc.perform(post("/tasks")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"B\",\"projectId\":" + projectId + ",\"labels\":[\"bug\"]}"))
                .andReturn().getResponse().getContentAsString();
        int t2 = JsonPath.read(t2Body, "$.id");
        mockMvc.perform(post("/tasks")
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"title\":\"C\",\"projectId\":" + projectId + ",\"labels\":[\"feature\"]}"));
        mockMvc.perform(patch("/tasks/" + t2)
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"status\":\"DONE\"}"));

        mockMvc.perform(get("/tasks").param("projectId", String.valueOf(projectId)).param("label", "bug"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()", is(2)));

        mockMvc.perform(get("/tasks")
                        .param("projectId", String.valueOf(projectId))
                        .param("label", "bug")
                        .param("status", "DONE"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()", is(1)))
                .andExpect(jsonPath("$[0].id", is(t2)));
    }

    @Test
    void updateReplacesLabels() throws Exception {
        int projectId = createProject();
        String body = mockMvc.perform(post("/tasks")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"A\",\"projectId\":" + projectId + ",\"labels\":[\"bug\"]}"))
                .andReturn().getResponse().getContentAsString();
        int taskId = JsonPath.read(body, "$.id");

        mockMvc.perform(patch("/tasks/" + taskId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"labels\":[\"urgent\",\"backend\"]}"))
                .andExpect(jsonPath("$.labels", containsInAnyOrder("urgent", "backend")));

        mockMvc.perform(patch("/tasks/" + taskId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"A2\"}"))
                .andExpect(jsonPath("$.labels", containsInAnyOrder("urgent", "backend")));
    }
}

